// Native comparison driver for the browser bridge; reads task-generated bytes.
#include <fstream>
#include <iterator>
#include <vector>
#include <iostream>
#include <string>
#include <opencv2/core/version.hpp>
extern "C" int cutout_segment(const unsigned char*,const unsigned char*,int,int,int,int,int,int,unsigned char*,unsigned char*);
extern "C" const char* cutout_error();
int main(int argc,char** argv) {
    if(argc==2 && std::string(argv[1])=="--version") { std::cout<<CV_VERSION<<'\n'; return 0; }
    if(argc!=10) return 2;
    const int w=std::stoi(argv[3]),h=std::stoi(argv[4]);
    std::ifstream image_file(argv[1],std::ios::binary),seed_file(argv[2],std::ios::binary);
    std::vector<unsigned char> rgba((std::istreambuf_iterator<char>(image_file)),{});
    std::vector<unsigned char> labels((std::istreambuf_iterator<char>(seed_file)),{});
    if(rgba.size()!=size_t(w)*h*4 || labels.size()!=size_t(w)*h) return 2;
    std::vector<unsigned char> output(rgba.size()),mask(labels.size());
    if(cutout_segment(rgba.data(),labels.data(),w,h,std::stoi(argv[5]),std::stoi(argv[6]),std::stoi(argv[7]),std::stoi(argv[8]),output.data(),mask.data())) {
        std::cerr<<cutout_error()<<'\n'; return 1;
    }
    std::ofstream(std::string(argv[9])+".rgba",std::ios::binary).write(reinterpret_cast<char*>(output.data()),output.size());
    std::ofstream(std::string(argv[9])+".mask",std::ios::binary).write(reinterpret_cast<char*>(mask.data()),mask.size());
}
